module student_top(
  input         clock,
                reset,
  output [31:0] araddr,
  output        arvalid,
  input         arready,
  input  [31:0] rdata,
  input  [1:0]  rresp,
  input         rvalid,
  output        rready,
  output [31:0] awaddr,
  output        awvalid,
  input         awready,
  output [31:0] wdata,
  output [3:0]  wstrb,
  output        wvalid,
  input         wready,
  input  [1:0]  bresp,
  input         bvalid,
  output        bready
);
  /* verilator no_inline_module */

  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & (|rresp)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: AXI4-Lite read response must be OKAY\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (~reset & (|bresp)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: AXI4-Lite write response must be OKAY\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  CPU cpu (
    .clock      (clock),
    .reset      (reset),
    .io_araddr  (araddr),
    .io_arvalid (arvalid),
    .io_arready (arready),
    .io_rdata   (rdata),
    .io_rvalid  (rvalid),
    .io_rready  (rready),
    .io_awaddr  (awaddr),
    .io_awvalid (awvalid),
    .io_awready (awready),
    .io_wdata   (wdata),
    .io_wstrb   (wstrb),
    .io_wvalid  (wvalid),
    .io_wready  (wready),
    .io_bvalid  (bvalid)
  );
  assign bready = 1'h1;
endmodule

